// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
        // give the contract some balance (via its payable fallback path / deal)
        vm.deal(address(c), 1 ether);
    }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any withdrawal amount exceeding the contract's balance.
        // This is the widest domain in which the deleted transfer is still obligated
        // to fire (and therefore to fail) in the reference.
        vm.deal(address(c), 1 ether);
        amount = bound(amount, address(c).balance + 1, type(uint256).max);

        // owner is the deployer (this test contract)
        bool ok = true;
        vm.prank(address(this));
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an owner withdrawal of more than the contract's balance
        // must fail — the transfer cannot succeed, so the call must revert.
        // Reference: always reverts here. Mutant: transfer deleted, call succeeds.
        assertTrue(!ok, "withdraw exceeding balance must revert");
    }
}
